import numpy as np
import pandas as pd
import pytest
import common as C
from conftest import ROOT, load_stage

SIZE = "AREA PERIMETER MAJOR_AXIS MINOR_AXIS EQDIASQ CONVEX_AREA EXTENT".split()


@pytest.fixture(scope="module")
def splits():
    p = ROOT / "data" / "splits.csv"
    if not p.exists():
        pytest.skip("data/splits.csv not built")
    return pd.read_csv(p)


def test_grain_ids_unique_and_disjoint(splits):
    assert splits.grain_id.is_unique
    sets = {s: set(splits[splits.split == s].grain_id) for s in ("train", "val", "test")}
    assert not (sets["train"] & sets["val"]) and not (sets["train"] & sets["test"]) and not (sets["val"] & sets["test"])
    assert sum(map(len, sets.values())) == len(splits)


def test_class_and_lot_shares_match(splits):
    for col, tol in (("class", 0.01), ("lot", 0.02)):
        sh = pd.crosstab(splits.split, splits[col], normalize="index")
        assert (sh.max() - sh.min()).max() < tol, sh


def test_sizefree_lists_have_no_size_columns():
    for fs in ("sizefree7", "sizefree22"):
        assert not set(C.features(fs)) & set(SIZE)
    assert set(C.features("sizefree7")) <= set(C.features("sizefree22"))


def test_feature_sets_are_inside_all106():
    for fs in ("all106", "distinct91", "shape16", "colour90", "sizefree7", "sizefree22"):
        assert set(C.features(fs)) <= set(C.ALL106)
    assert len(C.features("all106")) == 106


def test_grey_world_gains_use_mask_only():
    m = load_stage("09_robustness.py")
    img = np.zeros((20, 20, 3), np.uint8)
    img[5:15, 5:15] = (200, 100, 50)
    mask = np.zeros((20, 20), bool); mask[5:15, 5:15] = True
    g = m.grey_world_gains(img, mask)
    np.testing.assert_allclose(g, (350 / 3) / np.array([200, 100, 50]))
    img2 = img.copy(); img2[0:3, 0:3] = 255            # background changes must not move the gain
    np.testing.assert_allclose(m.grey_world_gains(img2, mask), g)
    corrected = m.apply_gains(img, g)[mask]
    assert np.ptp(corrected.mean(0)) < 1.5              # grain channels equalised
    np.testing.assert_array_equal(m.grey_world_gains(img, None), np.ones(3))


def test_unit_gain_leaves_image_unchanged():
    m = load_stage("09_robustness.py")
    img = np.random.default_rng(0).integers(0, 256, (8, 8, 3), dtype=np.uint8)
    np.testing.assert_array_equal(m.apply_gains(img, np.ones(3)), img)


def test_floor_for_and_wilson():
    conf = np.array([0.5, 0.9, 0.95, 0.99]); ok = np.array([0, 1, 1, 1])
    assert C.floor_for(conf, ok, 1.0) == 0.9
    assert C.floor_for(conf, np.zeros(4), 1.0) == 1.01
    lo, hi = C.wilson(50, 100)
    assert lo < 0.5 < hi
